/* Read-only explanations beside gang summary values; calculations remain in MMFinancials. */
(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,P=(en,ko)=>`<p>${L(en,ko)}</p>`,num=x=>Number.isFinite(Number(x))?Number(x):0,F=()=>window.MMFinancials,fmt=x=>num(x).toLocaleString('en-US');
const fields={rating:['Gang Rating','갱 레이팅'],reputation:['Reputation','명성'],credits:['Credits','크레딧'],tp:['Trade Points (TP)','거래 포인트(TP)'],wealth:['Wealth','자산'],size:['Gang Size','갱 규모']};
const contextKeys={'gang.rating':'rating','gang.reputation':'reputation','gang.credits':'credits','equipment.trade-points':'tp','gang.wealth':'wealth','gang.size':'size'},keysByLabel={'Rating:':'rating','Reputation:':'reputation','Credits:':'credits','Trade Points:':'tp','Wealth:':'wealth','Gang Size:':'size'};
const ids={rating:['n26-core-gang-finances','n26-core-tactics-selection'],reputation:['n26-core-gang-finances','n26-core-reputation'],credits:['n26-core-gang-budget','n26-core-visit-trading-post'],tp:['n26-core-visit-trading-post'],wealth:['n26-core-gang-finances'],size:['n26-core-gang-finances']};
const contextKey=key=>Object.keys(contextKeys).find(k=>contextKeys[k]===key),ed=g=>String(g?.edition||g?.edition_slug||'').toLowerCase(),selected=()=>typeof gang==='function'?gang():null;
function sourceRows(key,g){if(ed(g)!=='n26')return [];return (ids[key]||[]).map(id=>(window.RULES_DATA?.coreRules||[]).find(r=>r.id===id&&r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26')).filter(Boolean);}
function value(key,g){return key==='rating'?F().rating(g):key==='wealth'?F().wealth(g):key==='size'?F().gangSize(g):num(g[key==='tp'?'tradePoints':key]);}
function fold(key,en,ko,body){return `<details class="gs-section" data-gang-stat-section="${key}"><summary>${L(en,ko)}</summary><div>${body}</div></details>`;}
function rowsMarkup(rows){return '<dl class="gs-breakdown">'+rows.map(r=>`<div><dt>${r.labelKo?L(r.label,r.labelKo):`<span data-user-text>${E(r.label)}</span>`}</dt><dd>${E(fmt(r.value))}</dd></div>`).join('')+'</dl>';}
function record(key,g){
 const eligible=(g.fighters||[]).filter(F().active),excluded=(g.fighters||[]).filter(f=>!F().active(f));let rows=[];
 if(key==='wealth')rows=F().wealthRows(g).map(r=>({...r,labelKo:({'Gang Rating':'갱 레이팅','Credits':'크레딧','Stash':'보관함 장비','Vehicles (without crew)':'크루 미배정 차량'})[r.label]}));
 else if(key==='rating'){rows=eligible.map(f=>({label:f.name||f.type||'—',value:F().fighterValue(g,f)}));if(F().allianceTithe(g))rows.push({label:'Recorded alliance tithe',labelKo:'기록된 동맹 추가 비용',value:F().allianceTithe(g)});}
 else if(key==='size')rows=F().compositionRows(g);
 else rows=[{label:fields[key][0],labelKo:fields[key][1],value:value(key,g)}];
 return `<div class="gs-live-value">${L('Current saved value','현재 저장된 값')} <strong>${E(fmt(value(key,g)))}</strong>${key==='tp'?' TP':''}</div>`+rowsMarkup(rows)+(key==='tp'?P('This is the recorded TP balance. The app does not generate TP merely because a Leader or Champion is on the roster, nor automatically expire it by time. Use the campaign Trading Post to record completed visits and finish the sub-step, or record manual adjustments in Resources.','현재 기록된 TP 잔액입니다. 리더·챔피언을 보유했다는 이유만으로 TP를 만들거나, 시간이 지났다고 자동 만료시키지는 않습니다. 캠페인 트레이딩 포스트에서 완료한 방문과 단계 종료를 기록하거나, 직접 조정할 때는 자원에서 기록하세요.'):key==='rating'||key==='size'?P('This screen counts In Recovery models. Captured, Dead, Retired, Enslaved and Destroyed statuses, or their recorded exclusion flags, are excluded by the current app calculation. Starting crew is a separate selection.','이 화면은 회복 중인 모델을 포함합니다. 포획·사망·은퇴·노예·파괴 상태 또는 그에 해당하는 제외 표시는 현재 앱 집계에서 제외합니다. 시작 크루 선택과는 별개입니다.')+(excluded.length?`<p class="gs-record-note">${L('Excluded records to review','집계에서 제외된 기록 확인')}: ${excluded.map(f=>`<span data-user-text>${E(f.name||'—')} (${E(f.status||'—')})</span>`).join(' · ')}${ed(g)==='n26'&&key==='rating'?' · '+L('The N26 rule refers to every roster model; check these records when comparing the full roster value.','N26 원문은 전체 명단 모델을 기준으로 합니다. 전체 명단 가치를 비교할 때 이 기록들을 확인하세요.'):''}</p>`:''):key==='wealth'?P('The breakdown uses the app’s recorded model and item values, including quantities. TP and Reputation are not added to Wealth.','내역은 앱에 기록된 모델·장비 가치와 수량으로 계산합니다. TP와 명성은 자산 합계에 더하지 않습니다.'):key==='credits'?P('Only recorded transactions change this balance. Reading this guide never spends credits or moves equipment.','기록한 거래만 이 잔액에 반영됩니다. 설명을 읽어도 크레딧이 차감되거나 장비가 이동하지 않습니다.'):P('This is the saved Reputation. Rules may specify a reward or loss; the app does not grant it simply because a fighter was recruited.','현재 저장된 명성입니다. 보상·손실은 해당 규칙에 따르며 파이터를 모집했다는 이유만으로 자동 증가하지 않습니다.'));
}
const descriptions={
 rating:{summary:['The credit value of the gang’s roster models and their equipment. It describes the value of the force, not cash available to spend.','명단 모델과 보유 장비의 크레딧 가치입니다. 갱의 전력 가치를 나타내며, 지금 쓸 수 있는 돈은 아닙니다.'],usage:['Use the full Gang Rating when a scenario or campaign asks you to compare gangs. N26 Gang Tactics gives the lower-rated gang one extra selection per full 200-credit gap; it does not use just the starting crew.','시나리오·캠페인에서 갱의 가치를 비교할 때 씁니다. N26 갱 택틱은 전체 갱 레이팅이 낮은 쪽에 차이 200크레딧마다 선택 1개를 더 줍니다. 시작 크루만의 합계로 계산하지 않습니다.'],example:['Example: Rating 950 against 1,350 gives a 400 gap. The lower-rated gang gains 2 extra tactic selections, making 3 with its base 1. Stash cash and unequipped Stash items are not added to Rating.','예: 레이팅 950 대 1,350이면 차이는 400입니다. 낮은 쪽은 택틱 선택 2개를 추가해 기본 1개와 합계 3개입니다. 보관함의 현금·미지급 장비는 레이팅에 더하지 않습니다.']},
 reputation:{summary:['A campaign measure of the gang’s reputation. It is separate from credits, TP and the number of fighters.','캠페인에서 쌓이는 갱의 평판 수치입니다. 크레딧·TP·파이터 인원 수와 별개입니다.'],usage:['Apply Reputation rewards and losses specified by missions or campaign rules. N26 starts at 1, never falls below 1, and applies gains before losses when both occur in the same resolution.','미션·캠페인 규칙이 정한 명성 보상과 손실을 적용할 때 씁니다. N26에서는 1로 시작하고 1 미만으로 내려가지 않습니다. 같은 처리에 증가·감소가 함께 있으면 증가를 먼저 적용합니다.'],example:['Example: start at 1, gain 2 and lose 4 in the same resolution. Add first: 1 → 3. Then subtract, stopping at the minimum: 3 → 1. Do not turn Reputation into extra credits or TP.','예: 명성 1에서 같은 처리에 +2와 −4를 받았다면, 먼저 1 → 3으로 올린 뒤 감소를 적용합니다. 최솟값이 1이므로 최종 명성은 1입니다. 명성을 크레딧이나 TP로 바꿔 계산하지 않습니다.']},
 credits:{summary:['The gang’s recorded spendable cash. Equipment already owned is recorded as an asset, not as cash in this number.','갱이 현재 쓸 수 있는 현금 잔액입니다. 이미 산 장비의 가치는 이 잔액과 별도로 기록됩니다.'],usage:['Use credits to pay recruitment and equipment costs and record campaign income or rewards. N26 campaign founding credits left unspent go into the Stash; unused skirmish founding credits are lost. A Trading Post purchase may also need TP and an eligible visitor.','모집·장비 구입 비용을 내고 캠페인 수입·보상을 기록할 때 씁니다. N26 캠페인 창설 때 남은 크레딧은 보관함에 남지만, 스커미시 창설 때 쓰지 않은 예산은 사라집니다. 거래소 구매에는 별도로 TP와 자격 있는 방문자가 필요할 수 있습니다.'],example:['Example: with 50 credits, buying equipment for 20 leaves 30. If its recorded value is also 20 and nothing else changes, Rating 950 becomes 970 while Wealth stays 1,000: 950 + 50 = 970 + 30.','예: 50크레딧에서 장비를 20에 사면 잔액은 30입니다. 장비의 기록 가치도 20이고 다른 변동이 없다면 레이팅 950은 970이 되지만, 자산은 950 + 50 = 970 + 30 = 1,000으로 같습니다.']},
 tp:{summary:['Trade Points are a separate N26 resource spent alongside credits to acquire Trading Post equipment. They are not credits, Reputation or fighter XP.','거래 포인트(TP)는 N26 거래소 장비를 구할 때 크레딧과 함께 쓰는 별도 자원입니다. 크레딧·명성·파이터 XP가 아닙니다.'],usage:['During the Post-cycle Visit the Trading Post sub-step, a visiting Leader generates 2 TP and a Champion 1 TP. At least one eligible visitor is required for Trading Post purchases. Spend both the listed credits and TP; unused TP expire at the end of that sub-step.','사이클 종료 후의 비지트 더 트레이딩 포스트 단계에서 방문한 리더는 2TP, 챔피언은 1TP를 만듭니다. 거래소 구매에는 자격 있는 방문자가 최소 1명 필요합니다. 품목의 크레딧과 TP를 모두 지불하며, 해당 단계에 쓰지 않은 TP는 단계 종료 때 소멸합니다.'],example:['Example prices for explanation: a Leader and Champion visit, generating 3 TP. With 100 credits, buy a 50-credit / 2-TP item: 50 credits and 1 TP remain. That unused 1 TP expires at the end of this visit sub-step. Having 100 credits and 0 TP is insufficient for that item.','설명용 가격 예시: 리더와 챔피언이 방문하면 3TP입니다. 100크레딧으로 50크레딧·2TP 품목을 사면 50크레딧과 1TP가 남습니다. 남은 1TP는 이 방문 단계가 끝나면 소멸합니다. 100크레딧이 있어도 TP가 0이면 그 품목은 살 수 없습니다.'],extra:['Gang Equipment List purchases may be made without a visit under the core rule; ordinary list purchases do not spend TP in this app. TP “E” means Exclusive list access is required, not zero TP or unlimited access. Always check the fighter’s equipment restrictions.','코어 규칙상 갱 전용 장비 목록은 방문 없이 구매할 수 있고, 앱에서도 일반 전용 목록 구매는 TP를 쓰지 않습니다. TP의 E 표시는 Exclusive로 해당 장비 목록 접근이 필요하다는 뜻이며, 0TP나 무제한 허용이라는 뜻이 아닙니다. 파이터별 장비 제한도 확인하세요.']},
 wealth:{summary:['Total recorded assets: Gang Rating plus Stash credits and Stash equipment value. It describes everything owned in that calculation, not a second wallet.','갱 레이팅에 보관함 크레딧과 보관함 장비 가치를 더한 총자산입니다. 별도의 두 번째 지갑이 아닙니다.'],usage:['Use Wealth when a campaign compares accumulated assets. Cash, fielded model value and spare equipment have different jobs; compare the quantity the mission actually asks for. TP and Reputation do not contribute to this total.','캠페인에서 쌓은 자산을 비교할 때 씁니다. 현금·모델 가치·예비 장비는 서로 다른 수치이므로 미션이 요구한 항목을 비교하세요. TP와 명성은 이 합계에 더하지 않습니다.'],example:['Example: Rating 950 + credits 50 + Stash equipment 0 = Wealth 1,000. If a spare 30-credit weapon is in the Stash, Wealth becomes 1,030 while Rating remains 950 until that equipment is assigned to a counted model.','예: 레이팅 950 + 크레딧 50 + 보관함 장비 0 = 자산 1,000입니다. 예비 무기 30이 보관함에 있으면 자산은 1,030이지만, 집계 대상 모델에게 지급하기 전까지 레이팅은 950입니다.']},
 size:{summary:['The number of models counted on this gang’s roster by this screen. It is separate from their credit value and from the crew chosen for one battle.','이 화면이 집계하는 갱 명단 모델 수입니다. 모델들의 크레딧 가치나 한 전투에 고른 크루 인원과는 별개입니다.'],usage:['The N26 core rule sets no overall roster-size cap. Gang composition, model limits and the scenario’s crew selection still apply. A roster count of 9 does not automatically mean all 9 can deploy.','N26 코어 규칙은 전체 명단 인원 수 자체에 상한을 두지 않습니다. 다만 갱 편성 조건·모델별 제한·시나리오 크루 선택은 따로 적용합니다. 갱 규모가 9라고 해서 무조건 9명 모두 배치하는 것은 아닙니다.'],example:['Example: a gang has 9 counted models. A mission selecting a starting crew of 6 uses 6 eligible models initially; the remaining models are handled by that mission’s reserve rules. Do not change the gang’s recorded size to 6.','예: 집계 모델이 9명인 갱에서 미션이 시작 크루 6명을 정했다면 처음에는 참가할 수 있는 모델 6명을 사용하고, 나머지는 해당 미션의 예비·증원 규칙을 따릅니다. 갱 규모 기록을 6으로 바꾸는 것은 아닙니다.']}
};
function markup(key,g){
 if(!fields[key]||!g||!F())return '';const rr=sourceRows(key,g),verified=ed(g)==='n26'&&rr.length===ids[key].length,d=descriptions[key];
 const summary=verified?d.summary:['This screen shows the app’s recorded '+fields[key][0]+'. Official rules for this edition are not supplied by this N26 guide.','이 화면에 기록된 '+fields[key][1]+'입니다. 이 N26 가이드에서 다른 판본의 공식 규칙을 제공하지는 않습니다.'];
 return `<div class="gs-guide" data-gang-stat-guide="${key}" data-context-help-key="${contextKey(key)}"><div class="gs-current"><span>${L('Current display','현재 표시')}</span><strong>${E(fmt(value(key,g)))}</strong>${key==='tp'?'<b>TP</b>':''}</div><div class="gs-summary">${P(...summary)}</div>${verified?fold('usage','When do I use it?','언제·어디에 쓰나',P(...d.usage)+(d.extra?P(...d.extra):''))+fold('example','Example','계산·플레이 예시',P(...d.example)):P('Use your edition’s rulebook or agreed campaign pack. The record breakdown below only explains the app display.','해당 판본의 룰북·합의한 캠페인 팩을 확인하세요. 아래 내역은 앱의 표시 값만 설명합니다.')}${fold('record','This gang’s recorded breakdown','이 갱의 현재 내역',record(key,g))}${verified?fold('rules','Verified N26 rules','확인된 N26 원문 규칙',rr.map(r=>`<button type="button" class="btn small" data-rule-term="${E(r.id)}" data-rule-edition="n26">${L(r.name,r.name_ko||r.name)}</button>`).join('')):''}</div>`;
}
function open(key,options={}){const g=options.gang||selected();if(!g||!fields[key])return false;const body=markup(key,g);return body?window.MMRuleReference?.openContext(fields[key][0],body,{nameKo:fields[key][1]+' 설명',activator:options.activator||document.activeElement,nested:!!document.querySelector('.mmrr-overlay')})||false:false;}
const previous=gangTop;gangTop=function(g){const host=document.createElement('div');host.innerHTML=previous(g);const facts=host.querySelector('.entity-facts');if(!facts)return host.innerHTML;for(const child of [...facts.children]){const label=[...child.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim(),key=keysByLabel[label];if(!key||child.querySelector('[data-gang-stat-help]'))continue;const wrap=document.createElement('div');wrap.className='gs-metric';wrap.dataset.gangStat=key;child.before(wrap);child.classList.add('gs-stat-original');wrap.append(child);const button=document.createElement('button');button.type='button';button.className='gs-stat-help';button.dataset.gangStatHelp=key;button.dataset.gangStatGang=g.id;button.setAttribute('aria-haspopup','dialog');button.dataset.i18nEnAriaLabel=fields[key][0]+' — View explanation';button.dataset.i18nKoAriaLabel=fields[key][1]+' 설명 보기';button.setAttribute('aria-label',button.dataset.i18nEnAriaLabel);button.innerHTML='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 7v.1"/></svg>';wrap.append(button);}return host.innerHTML;};
window.addEventListener('click',event=>{const button=event.target.closest?.('[data-gang-stat-help]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const g=typeof data!=='undefined'?(data.gangs||[]).find(g=>g.id===button.dataset.gangStatGang):null;if(g)open(button.dataset.gangStatHelp,{gang:g,activator:button});},true);
window.MMGangStatGuide={open,markup,contextKeys};
})();
